#    `--restore` 之后它又回到根目录 config.json，_test_bigmoney_gate ① 就反复变红
#    （实测：config.json mtime = --restore 时刻，_deploy_tmp/config.json 里照样带着这个键）。
#    在这里一次性从**包内**剔除：包干净 → 上传后云端副本也干净 → 以后不会再回流。
# ⛔ 只能扫「代码侧已无读取路径」的键；拿不准的不许往这里加（删错了就是用户配置丢了）。
RETIRED_CFG_KEYS = ["bigMoneyProbGate"]

# 绝不进发布包的文件：access.json 含密码哈希/设备台账/签名密钥(machineKey)，
# 一旦随包发布，每次上线都会把线上的覆盖回本地旧副本（u 版起 machineKey 就存这里）。
# _deploy_tmp 是长期复用的目录，旧流程曾整目录拷贝，这里每次发布前强制清一遍。
NEVER_SHIP = ["access.json", "server.log"]


def post(path, obj):
    req = urllib.request.Request(ONLINE + path, data=json.dumps(obj).encode("utf-8"), method="POST",
                                 headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.load(r)


def get(path):
    with urllib.request.urlopen(ONLINE + path, timeout=30) as r:
        return json.load(r)


def refresh_sync_token(cfgp):
    """⛔ 令牌保鲜（2026-10-05 修，实测日志里 41 次同步被拒全是这个坑）

    --restore 会把 config.json 还原成【发版前】的备份，里面的 syncUpstream.token 是发布那一刻
    签的旧令牌；而发版过程会 bump 世代号 → 旧令牌当场作废。
    表现：本机面板改持仓 / 改配置，线上全部拒收（server.log 刷 `[sync↑] 线上拒绝了`，
    错误原因为空 = 被口令闸门拦），手机上永远看不到改动，而且**不报错、不弹窗**，纯静默失败。

    _post_publish.py 也会重签，但它若跑在 --restore 之前就白做 → 这里再兜一次底，
    并且**签完立刻用线上接口验一次**，验不过就大声报错，别再让它静默烂掉。
    """
    try:
        tr = post("/api/lock/trust", {"password": DEV_PWD, "name": "本机副本同步",
                                      "role": "edit", "fp": "FPUB_SYNC02"})
        if not tr.get("ok"):
            print("   ⚠️ 转发令牌重签失败：%s（本机改持仓将不会同步到手机）" % (tr.get("error") or tr))
            return False
        tok = tr.get("deviceToken") or ""
        if len(tok) < 80:
            print("   ⚠️ 拿到的是短令牌(%d 位)，不是 deviceToken —— 已放弃写入" % len(tok))
            return False
        # 验真：用线上写接口探一下（未知 action 不会写任何数据、不会触发推送）
        probe = post("/api/holdings", {"token": tok, "action": "__probe_noop__"})
        if probe.get("locked") or probe.get("needPassword"):
            print("   ⚠️ 新令牌线上不认（可能被世代号作废）—— 已放弃写入")
            return False
        cfg = json.load(open(cfgp, encoding="utf-8"))
        su = cfg.setdefault("syncUpstream", {})
        su["enabled"] = True
        su["url"] = ONLINE
        su["token"] = tok
        cfg["pushRole"] = "replica"
        with open(cfgp, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
        print("   ✅ 已重签并验证 syncUpstream.token（%d 位）→ 本机改动可同步到手机" % len(tok))
        # 台账卫生：同一个 fp 只留最新一条，别每次发版都往用户台账里堆一行
        try:
            items = (get("/api/lock/devices?token=" + urllib.parse.quote(tok)) or {}).get("items", [])
            same = sorted([x for x in items if x.get("fp") == "FPUB_SYNC02"],
                          key=lambda x: x.get("ts") or 0)
            for x in same[:-1]:
                post("/api/lock/revoke", {"id": x.get("id", ""), "token": tok})
        except Exception:
            pass
        return True
    except Exception as e:
        print("   ⚠️ 转发令牌重签异常：%s（本机改持仓将不会同步到手机）" % e)
        return False


# ── 发布卫生 + 包体闸门（2026-10-23 包体事故的根治措施）──────────────────────
# 发布工具上传的是【整个 ROOT】的压缩包，CloudStudio 网关有约 800MiB 请求体上限
# （实证：804MiB 秒 RST、798MiB 成功）。历史上源码 zip/日志/暂存区在 ROOT 里
# 无限堆积，把包从 270MB 拱到 804MB。三道防线：
#   ① hygiene_root()：sync 时把名单内的 inert 产物自动挪去工件目录（只挪不删）；
#   ② trim_kline_cache()：sync 时把发布包里的 K线缓存裁到「最近 N 个月有数据」的票；
#   ③ size_gate()：sync 完成与 --apply 前各数一遍 ROOT 原始字节，越线拒发。
# ⛔  hygiene 只认名单里的模式，绝不碰业务文件（.kline_cache/DATA_FILES/代码）。
GATE_WARN_MIB = 600      # 警戒线：打印告警但放行
GATE_ABORT_MIB = 850     # 红线：直接拒发（经验压缩比≈0.8，850MiB 原始≈680MiB 归档，留余量）


def _months_ago(n):
    """今天往前 n 个自然月的日期（今天 10-23、n=3 → 2026-07-23；月末对齐取较小值）。"""
    t = datetime.date.today()
    y, m = t.year, t.month - n
    while m <= 0:
        m += 12
        y -= 1
    d = min(t.day, calendar.monthrange(y, m)[1])
    return datetime.date(y, m, d)


def trim_kline_cache(kc_dir, months=3):
    """把发布包里的 K线缓存裁到「最近 N 个月还有数据」的票（2026-10-23 用户提议落地）。

    实测结论（全量扫描 5925 个文件，不是抽样）：
    · 行数 min/中位/p90/max = 1/60/60/96，>100 行的文件 0 个——em.js fetchKline
      默认 days=95、fetchKlineThs 有 slice(-days)、klineRows 回源写 days=30，
      **活跃票的缓存本来就是 30~96 行的滚动窗口**，抓取层已经做到有界，
      「只保留三个月」对活跃票没有油水，不需要逐行裁历史。
    · 真正无界增长的只有【死票文件】：停牌/退市后永不更新，last date 越来越旧，
      却永远躺在缓存里随每次发布重传（400 只样本 27 只≈6.75%，约 400 只 / 4~5MB，
      且只会随未来的停牌/退市越积越多）。
    口径：整只删——最后一根柱的日期早于「今天往前 N 个自然月」即裁。
    ⛔ 只裁发布包（artifacts/_deploy_tmp），不裁 ROOT：四个守门测试拿真缓存当夹具
      （_test_learnall_valid/_test_tech_indicators/_test_trend_channel/_test_implicit_default），
      本地面板也要看。自愈由 klineRows 保证：死票被访问到时回源整窗重写文件
      （server.js klineRows ④），mtime 变新 → 下次同步的 10 天增量窗口把它抄回发布包。
    """
    if not os.path.isdir(kc_dir):
        return 0
    cut = _months_ago(months).isoformat()
    cut_ts = time.time() - months * 30 * 86400
    n = 0
    freed = 0
    skipped = 0
    for fn in os.listdir(kc_dir):
        if not fn.endswith(".json"):
            continue
        fp = os.path.join(kc_dir, fn)
        try:
            # mtime 短路：文件是最近才写的 ⇒ 最后一根柱必然新 ⇒ 活票，不必打开读。
            # ⛔ 沙箱负载实测（2026-10-23）：.kline_cache 的 decide_file 记录 15.3 万条，
            #   每次全量打开 5591 个 JSON 是 sandbox-center 130qps 突发的主源之一
            #   （突发负载下规则快照瞬时不可用 → fail-closed 拦截 Bash，秒级自愈）。
            #   只打开「mtime 也旧于截止线」的候选（实测约 400 个），打开次数降一个数量级。
            #   保守方向：新 mtime 但内容旧（极少见）本轮不裁，下轮 mtime 老化后自然被裁。
            if os.path.getmtime(fp) >= cut_ts:
                skipped += 1
                continue
            k = json.load(open(fp, encoding="utf-8"))
            rows = (k or {}).get("rows") or []
            last = max((str(r.get("date") or "")[:10] for r in rows), default="")
        except Exception:
            continue          # 读不出的不动它（宁留勿误删）
        if last and last < cut:
            try:
                freed += os.path.getsize(fp)
                os.remove(fp)
                n += 1
            except OSError:
                pass
    if n or skipped:
        print("   ✂️ K线缓存已裁 %d 只死票（最后一根数据早于 %s，发布包释放 %.1f MiB；%d 个新文件按 mtime 短路未读）"
              % (n, cut, freed / 1048576.0, skipped))
    return n


def hygiene_root():
    """发布前清扫根目录里的产物文件，挪去 ../stock-dashboard-artifacts/。"""
    art = ARTIFACTS
    moved = []
    rules = [
        ("量化看盘平台_*.zip", os.path.join(art, "源码包")),   # 每轮源码包（最大头）
        (".ztpre_feat.json", os.path.join(art, "cache")),      # 16MB 特征缓存（可重建）
    ]
    for pat, dst in rules:
        os.makedirs(dst, exist_ok=True)
        for f in glob.glob(os.path.join(ROOT, pat)):
            t = os.path.join(dst, os.path.basename(f))
            try:
                if os.path.exists(t) and os.path.getmtime(t) >= os.path.getmtime(f):
                    os.remove(f)          # 工件目录已有同名且更新 → 删根目录这份（防重复上传）
                    moved.append(os.path.basename(f) + "(去重)")
                    continue
                if os.path.exists(t):
                    os.remove(t)
                shutil.move(f, t)
                moved.append(os.path.basename(f))
            except Exception:
                pass
    # _old_zips/ 历史源码包归档目录
    oz = os.path.join(ROOT, "_old_zips")
    if os.path.isdir(oz):
        dst = os.path.join(art, "old_zips")
        os.makedirs(dst, exist_ok=True)
        for f in glob.glob(os.path.join(oz, "*")):
            t = os.path.join(dst, os.path.basename(f))
            if os.path.exists(t):
                continue
            try:
                shutil.move(f, t)
                moved.append("_old_zips/" + os.path.basename(f))
            except Exception:
                pass
    # 根目录 2 天以前的 *.log（近期日志可能正被进程持有，不碰）
    logdst = os.path.join(art, "logs")
    os.makedirs(logdst, exist_ok=True)
    _cut = time.time() - 2 * 86400
    for f in glob.glob(os.path.join(ROOT, "*.log")):
        try:
            if os.path.getmtime(f) >= _cut:
                continue
            t = os.path.join(logdst, os.path.basename(f))
            if os.path.exists(t):
                os.remove(f)
                moved.append(os.path.basename(f) + "(去重)")
                continue
            shutil.move(f, t)
            moved.append(os.path.basename(f))
        except Exception:
            pass
    # __pycache__（python 字节码缓存，每次 py_compile 都长，可再生）
    for d in glob.glob(os.path.join(ROOT, "__pycache__")):
        shutil.rmtree(d, ignore_errors=True)
    # ── 第二波（2026-10-23，用户「包体随修改增长」担忧）：惰性备份/诊断产物整目录出栈 ──
    # 逐个查过引用才进名单：server.js 只在注释里提到 backups/kline_dirty_bak（无运行时读取），
    # 其余只被一次性工具引用（_backfill_nd/_void_ghosts/_void_offauction/_clean_dirty_kline/
    # _clean_devices/_fetch_ztpool_*，都已跑完）。这些留档每次发版都随包重传，是 ROOT 里
    # 继 .kline_cache 之后的第二大堆积源（实测约 26MB）。
    # ⛔ 故意不搬的（查过特意留下）：
    #   _local_backup/   —— --restore 的数据源，且 _test_src_priv_channel 钉着，必须留在 ROOT；
    #   *.json.bak 家族  —— _post_publish ⑨ 每次发布现写的安全网（今天的时间戳，活的）；
    #   server.js.bak    —— 面板 /api/source 改源码的回滚副本（EDITABLE_SRC 机制活跃）；
    #   .holdings_bak/   —— holdings.js 写操作快照，运行中持续写入；
    #   _bak_dy/         —— grep -l 曾命中守门测试但复现不出，存疑即不动（428K，无关痛痒）。
    inert_dst = os.path.join(art, "inert")
    os.makedirs(inert_dst, exist_ok=True)
    _stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
    for name in ["backups", ".nd_backfill_bak", ".holiday_ghost_bak", ".offauction_bak",
                 ".kline_dirty_bak", ".device_cleanup_bak", ".ztpool_hist",
                 "_backup_before_wipe_20261005_015729"]:
        src = os.path.join(ROOT, name)
        if not os.path.isdir(src):
            continue
        t = os.path.join(inert_dst, name)
        try:
            if os.path.exists(t):      # 工件目录已有同名 → 加时间戳保留两边，绝不覆盖
                t = os.path.join(inert_dst, name + "_" + _stamp)
            shutil.move(src, t)
            moved.append(name + "/")
        except Exception:
            pass
    for name in ["_tmp_export.json", "online_index.html",
                 ".online_state.json", ".online_state2.json", ".online_state3.json",
                 ".online_state4.json", ".online_state_chk.json", ".online_state_chk2.json",
                 "stats_pre_backfill_20261014.json", "stats.json.bak_fix0928",
                 "stats.json.bak_nd", "决策台账_20261013.json.bak"]:
        src = os.path.join(ROOT, name)
        if not os.path.isfile(src):
            continue
        t = os.path.join(inert_dst, name)
        try:
            if os.path.exists(t):
                t = os.path.join(inert_dst, name + "_" + _stamp)
            shutil.move(src, t)
            moved.append(name)
        except Exception:
            pass
    if moved:
        print("   🧹 发布卫生：已清出根目录产物 %d 项 → stock-dashboard-artifacts/：%s%s"
              % (len(moved), "、".join(moved[:6]), " 等" if len(moved) > 6 else ""))
    return moved


def root_bytes():
    """ROOT 的原始字节数（口径=发布工具的打包容器：排除 .git/node_modules/build）"""
    total = 0
    for dirpath, dirnames, filenames in os.walk(ROOT):
        rel = os.path.relpath(dirpath, ROOT)
        top = rel.split(os.sep)[0] if rel != "." else ""
        if top in (".git", "node_modules", "build", "dist"):
            dirnames[:] = []
            continue
        for f in filenames:
            try:
                total += os.path.getsize(os.path.join(dirpath, f))
            except OSError:
                pass
    return total


SIZE_LEDGER = os.path.join(ARTIFACTS, "publish_sizes.jsonl")


def _ledger_record(mib):
    """包体时间线：每次自检落一行（修剪到最近 600 行 ≈ 两年半），供增长趋势 Early-Warning。"""
    try:
        os.makedirs(ARTIFACTS, exist_ok=True)
        with open(SIZE_LEDGER, "a", encoding="utf-8") as f:
            f.write(json.dumps({"ts": datetime.datetime.now().isoformat(timespec="seconds"),
                                "mib": round(mib, 1)}, ensure_ascii=False) + "\n")
        lines = open(SIZE_LEDGER, encoding="utf-8").read().strip().split("\n")
        if len(lines) > 600:
            with open(SIZE_LEDGER, "w", encoding="utf-8") as f:
                f.write("\n".join(lines[-600:]) + "\n")
    except Exception:
        pass


def _ledger_trend(mib):
    """近 30 天增长速率 → 按此速率离警戒/红线还有多少个月。

    ⛔ 这是 Early-Warning 不是算命：速率按近 30 天首尾差线性外推，只为让「包体是不是在
    不知不觉中变大」变成可测量的事实——真到了红线前面还有 size_gate 硬拦。"""
    try:
        if not os.path.isfile(SIZE_LEDGER):
            return ""
        now = datetime.datetime.now()
        rows = []
        for ln in open(SIZE_LEDGER, encoding="utf-8"):
            try:
                r = json.loads(ln)
                t = datetime.datetime.fromisoformat(r["ts"])
                if (now - t).days <= 30:
                    rows.append((t, float(r["mib"])))
            except Exception:
                continue
        if len(rows) < 2:
            return ""
        rows.sort()
        span_raw = (rows[-1][0] - rows[0][0]).total_seconds() / 86400.0
        if span_raw < 1.0:
            # 同一天内的多条记录（sync+apply 各一条）外推月率是噪声，如实说「趋势要跨天才可算」
            return ("   📈 包体时间线：本轮 %.1f MiB（当日 %.1f→%.1f，共 %d 条；增长趋势需跨天才能算，下轮起展示）"
                    % (mib, rows[0][1], rows[-1][1], len(rows)))
        span_d = max(span_raw, 1.0)
        rate = (rows[-1][1] - rows[0][1]) / span_d * 30.0          # MiB/月
        if rate < -0.05:
            return "   📈 包体时间线：近30天 %.1f→%.1f MiB，月增 %+.1f（包体在缩小）" % (rows[0][1], rows[-1][1], rate)
        if rate <= 0.05:
            return "   📈 包体时间线：近30天 %.1f→%.1f MiB，月增 %+.1f（基本零增长）" % (rows[0][1], rows[-1][1], rate)
        return ("   📈 包体时间线：近30天 %.1f→%.1f MiB（月增 +%.1f）→ 按此速率警戒线还有 ~%.0f 个月、红线 ~%.0f 个月"
                % (rows[0][1], rows[-1][1], rate,
                   (GATE_WARN_MIB - mib) / rate, (GATE_ABORT_MIB - mib) / rate))
    except Exception:
        return ""


def size_gate():
    """上传前包体自检：越线拒发；记录包体时间线并打印增长趋势。返回原始 MiB。"""
    mib = root_bytes() / 1048576.0
    if mib > GATE_ABORT_MIB:
        raise SystemExit(
            "⛔ 发布中止：ROOT 原始内容 %.1f MiB，超过包体红线 %d MiB。\n"
            "   CloudStudio 网关约 800MiB 请求体上限，越线必被秒 RST（2026-10-23 连续 8 次失败的根因）。\n"
            "   请清理 ROOT 里的堆积物（源码 zip/日志/大缓存挪到 %s），或用 hygiene_root() 名单补充模式。"
            % (mib, GATE_ABORT_MIB, ARTIFACTS))
    if mib > GATE_WARN_MIB:
        print("   ⚠️ 包体告警：ROOT 原始 %.1f MiB（警戒 %d / 红线 %d）——该清理产物了"
              % (mib, GATE_WARN_MIB, GATE_ABORT_MIB))
    else:
        print("   📏 包体自检：ROOT 原始 %.1f MiB（警戒 %d / 红线 %d，余量充足）"
              % (mib, GATE_WARN_MIB, GATE_ABORT_MIB))
    _ledger_record(mib)
    _t = _ledger_trend(mib)
    if _t:
        print(_t)
    return mib


# 🧟 幽灵持仓防线（ld 轮 2026-10-27）：发布包循环搬运复活 —— sync 把线上磁盘持仓拉进包 →
#     包发回线上 → 容器回收冷启动回退发布包 → 用户已删的票随旧包复活 → 触发真告警
#     （10-23 晚 / 10-27 凌晨 600519 两次实证）。ops 流水救不了：用户删除发生在部署之后，
#     回退时 ops 跟包一起回退，证据原地蒸发（实测线上 ops=0 条）。
# 证据源：本地副本（唯一不回退的观测点）每次成功回拉都把「线上权威码表+时刻」追加进
#     .holdings_pull_history.json（server.js _recordPullHistory）。
# 判罪（三条同时成立才剔，逐票）：addedAt 非零 + 早于最后一次观测时刻 T_p + 那次观测不含它
#     + ops 无更晚的 re-add/restore 证据。防误伤：真实重加一定刷新 addedAt（add/remote-add）；
#     一键还原不刷 addedAt，靠 ops 的 restore 记录认；无 addedAt / 无观测史 / 判不出 → 一律放行。
def ghost_filter_holdings(items, pull_hist, ops):
    """返回 (保留列表, 定罪列表)。pull_hist: [{t,codes}]（取最后一条）；ops: [{t,act,added,removed,afterBrief}]"""
    convicted = []
    if not isinstance(items, list):
        return (items if isinstance(items, list) else []), convicted
    if not isinstance(pull_hist, list) or not pull_hist:
        return items, convicted          # 无观测史 → 判不出，放行（绝不因判不出就丢票）
    _last = pull_hist[-1] if isinstance(pull_hist[-1], dict) else {}
    t_p = _last.get("t") or 0
    codes_p = set(str(c) for c in (_last.get("codes") or []))
    if not t_p:
        return items, convicted
    legit_after = set()                  # T_p 之后的合法回归通道证据
    for r in (ops if isinstance(ops, list) else []):
        if not isinstance(r, dict) or (r.get("t") or 0) <= t_p:
            continue
        for c in (r.get("added") or []):
            legit_after.add(str(c))
        if r.get("act") == "restore":    # afterBrief 格式 "code·name" 或 "code"
            for b in (r.get("afterBrief") or []):
                legit_after.add(str(b).split("·")[0])
    kept = []
    for it in items:
        _it = it if isinstance(it, dict) else {}
        code = str(_it.get("code") or "")
        t_add = _it.get("addedAt") or 0
        if code and t_add and t_p > t_add and code not in codes_p and code not in legit_after:
            convicted.append(it)
        else:
            kept.append(it)
    return kept, convicted


def main():
    # ① 用开发者密码换一个长期设备令牌（本机指纹固定，避免每次登录都堆一条记录）
    tr = post("/api/lock/trust", {"password": DEV_PWD, "name": "发布同步", "role": "edit", "fp": "FPUBLISH01"})
    if not tr.get("ok"):
        raise SystemExit("线上登录失败: %s" % tr.get("error"))
    token = tr.get("deviceToken") or ""
    print("① 线上登录 OK")

    # ② 拉回线上最新业务数据
    exp = get("/api/sync/export?token=" + urllib.parse.quote(token))
    if not exp.get("ok"):
        raise SystemExit("线上数据导出失败: %s" % exp.get("error"))
    print("② 线上 appVer = %s，已拉回业务数据" % exp.get("appVer"))

    # ⓪★ 记下线上 machineKey：设备令牌是用它签名的，发布时 access.json 会被本地副本覆盖，
    #    machineKey 一变 → 线上所有已签发令牌当场失效 → 手机上每次发版都要重新登录。
    #    这里把它留住，稍后铺回包内/根目录的 access.json，令牌即可跨发版存活。
    online_mk = exp.get("machineKey")
    # ★ 同理保住【线上登录凭据 + 已授权设备台账】：否则本地开发副本的旧 access.json
    #   会把用户刚改的密码打回旧值、把手机上的令牌作废（详见 _restore_access_auth 注释）。
    online_auth = exp.get("accessAuth")
    if online_auth:
        try:
            os.makedirs(BACKUP, exist_ok=True)
            with open(os.path.join(BACKUP, ".online_access_auth.json"), "w", encoding="utf-8") as _f:
                json.dump(online_auth, _f, ensure_ascii=False)
            print("   \U0001f510 已取得线上登录凭据与设备台账（发布时不被本地副本覆盖）")
        except Exception as e:
            print("   ⚠️ 线上凭据保存失败: %s" % e)
    else:
        print("   ⚠️ 线上未返回 accessAuth（旧版本）—— 本次发布后可能需要重新登录")
    if online_mk:
        with open(os.path.join(ROOT, ".online_machinekey"), "w", encoding="utf-8") as _f:
            _f.write(online_mk)
        print("   🔑 已取得线上 machineKey（保令牌跨发版存活）")
    else:
        print("   ⚠️ 线上未返回 machineKey —— 本次发布后已授权设备需重新登录")

    # ⓪b 发布卫生：把 ROOT 里堆积的产物清去工件目录（包体失控的根治，见 hygiene_root）
    hygiene_root()

    os.makedirs(DEPLOY, exist_ok=True)
    # ⓪ 清掉绝不进发布包的敏感文件（历史遗留，尤其 access.json）
    for name in NEVER_SHIP:
        fp = os.path.join(DEPLOY, name)
        if os.path.exists(fp):
            os.remove(fp)
            print("   ⛔ 已从发布包剔除 %s（含密钥/密码哈希，绝不随包上线）" % name)
    for name in DATA_FILES:
        obj = (exp.get("files") or {}).get(name)
        if obj is None:
            # 线上没有该文件时，用本地根目录的版本兜底打进发布包
            # （否则 _deploy_tmp 里没有它 → 发布后线上直接丢失。news.json 线上拉不到
            #   快讯源没法重建归档，丢了就是真丢）
            src_local = os.path.join(ROOT, name)
            if os.path.exists(src_local):
                shutil.copy2(src_local, os.path.join(DEPLOY, name))
                print("   · %s 线上无数据，用本地版本兜底（%d 字节）" % (name, os.path.getsize(os.path.join(DEPLOY, name))))
            else:
                print("   · %s 线上无数据，包内也没有 —— 该数据发布后会丢失！" % name)
            continue
        if name == "config.json":
            # 线上实例必须是推送源：副本标记不能带上去，否则手机一条提醒都收不到
            obj.pop("pushRole", None)
            # syncUpstream 是「本地→线上」的单向转发配置，只属于本地副本。
            # 万一它被写进线上配置，线上就会把写操作转发给自己（回环），这里强制剔除。
            if obj.pop("syncUpstream", None) is not None:
                print("   ⛔ 已从线上配置剔除 syncUpstream（防线上自我转发回环）")
            for _rk in RETIRED_CFG_KEYS:
                if obj.pop(_rk, None) is not None:
                    print("   · 已从线上配置剔除退役键 %s（代码侧已无读取路径，删了不影响任何行为）" % _rk)
        if name == "holdings.json":
            # 两端不一致时提醒一句：差异几乎都是用户在手机上自己增删的，以线上为准
            _on = len((obj or {}).get("items") or [])
            try:
                _loc = json.load(open(os.path.join(ROOT, name), encoding="utf-8"))
                _ln = len((_loc.get("items")) or [])
            except Exception:
                _ln = 0
            if _on != _ln:
                print("   ⚠️ 持仓 线上 %d 条 / 本地 %d 条 —— 以线上为准"
                      "（差异通常是你在手机上自己增删的，不要拿本地去补）" % (_on, _ln))
            # ▼▼ 2026-09-30 新增闸门（用户两次投诉「持仓又没有了」之后的硬防线）▼▼
            # 「线上非空 → 本地空」是正常的（你删了仓）；
            # 但「线上空 → 本地非空」极不正常：它不是删除，是数据从线上凭空消失。
            # 以前这一步会乖乖把空版本写进发布包 → 发完线上彻底空了 → 用户看到「持仓又没了」。
            # 现在遇到这种情况中止发布，并把本地那份完好的存下来，等你确认后再发。
            if _on == 0 and _ln > 0 and not FORCE_EMPTY_HOLDINGS:
                import datetime as _dt
                keep = os.path.join(BACKUP, "holdings_local_nonempty_" + _dt.datetime.now().strftime("%Y%m%d-%H%M%S") + ".json")
                try:
                    os.makedirs(BACKUP, exist_ok=True)
                    shutil.copy2(os.path.join(ROOT, name), keep)
                except Exception:
                    keep = "(保存失败，请直接看 " + os.path.join(ROOT, name) + ")"
                raise SystemExit(
                    "\n" + "=" * 68 + "\n"
                    "🛑 发布已中止：线上持仓是【空】的，本地却有 %d 条\n" % _ln +
                    "=" * 68 + "\n"
                    "  这不像你自己删了仓（那会两端都空），更像线上的数据凭空消失了。\n"
                    "  若直接发下去，本地那份好的也会被空版本覆盖 —— 就是所谓「又没有了」。\n\n"
                    "  本地完好的那份已留存: %s\n" % keep +
                    "  请三选一：\n"
                    "   ① 确认线上确实该是空的 → 加参数 --force-empty-holdings 重跑\n"
                    "   ② 想把本地这份救回线上 → 走面板「持仓 → 变更记录」一键还原\n"
                    "   ③ 都不确定 → 先别发，告诉我，我来查是谁清的\n" +
                    "=" * 68 + "\n")
        with open(os.path.join(DEPLOY, name), "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=2)
        print("   ✓ %s 已用线上版本回填（%d 字节）" % (name, os.path.getsize(os.path.join(DEPLOY, name))))

    # ⓪b ★ 2026-10-20 事故加固（每日回测 automation 线上实测发现）：上面「线上无数据→用本地
    #    根目录版本兜底」的路径是 shutil.copy2 原样拷贝 —— 本地副本的 config.json 带着
    #    pushRole='replica' 与指向自己的 syncUpstream，原样上线 = ① 线上从此一条推送都不发
    #   （isReplica 全拦，静默）② 线上写操作自我转发回环。导出路径本来就会剥这两个键，但
    #   兜底路径 continue 掉了剥离子句 —— 这里对落盘后的包内 config.json 再无条件剥一次，
    #   两条路径都覆盖（对已剥过的导出路径是幂等空操作）。
    _dep_cfg = os.path.join(DEPLOY, "config.json")
    if os.path.exists(_dep_cfg):
        try:
            _c = json.load(open(_dep_cfg, encoding="utf-8"))
            _hit = [k for k in ("pushRole", "syncUpstream") + tuple(RETIRED_CFG_KEYS) if k in _c]
            for k in _hit:
                _c.pop(k, None)
            if _hit:
                with open(_dep_cfg, "w", encoding="utf-8") as _f:
                    json.dump(_c, _f, ensure_ascii=False, indent=2)
                print("   ⛔ 包内 config.json 复剥掉 %s（兜底路径加固：防线上退化为副本/自我回环）" % "/".join(_hit))
        except Exception as _e:
            print("   ⚠️ 包内 config.json 复剥失败：%s —— 请人工确认包内无 pushRole/syncUpstream 再发布！" % _e)

    # ⓪c 🧟 幽灵持仓防线（2026-10-27）：两条来源路径（线上回填 / 本地兜底）统一在这里过闸，
    #    判据与防误伤见 ghost_filter_holdings；定罪 = 容器回退从旧包复活的票，逐票剔除出包。
    _dep_hold = os.path.join(DEPLOY, "holdings.json")
    if os.path.exists(_dep_hold):
        try:
            _ho = json.load(open(_dep_hold, encoding="utf-8"))
            _hist = None
            _hp = os.path.join(ROOT, ".holdings_pull_history.json")
            if os.path.exists(_hp):
                _hist = json.load(open(_hp, encoding="utf-8"))
            _ops = (exp.get("files") or {}).get(".holdings_ops.json")
            if not isinstance(_ops, list):
                try:
                    _ops = json.load(open(os.path.join(ROOT, ".holdings_ops.json"), encoding="utf-8"))
                except Exception:
                    _ops = []
            if isinstance(_hist, list) and _hist and isinstance(_ho, dict):
                _kept, _conv = ghost_filter_holdings(_ho.get("items") or [], _hist, _ops or [])
                if _conv:
                    _ho["items"] = _kept
                    with open(_dep_hold, "w", encoding="utf-8") as _f:
                        json.dump(_ho, _f, ensure_ascii=False, indent=2)
                    print("   🧟 幽灵防线：发布包剔除 %d 只复活票（addedAt 早于最后一次线上权威观测且观测不含它）: %s"
                          % (len(_conv), ", ".join("%s·%s" % (x.get("code"), x.get("name") or "?") for x in _conv)))
                    print("       证据: .holdings_pull_history.json 最后观测 t=%d codes=[%s] —— 这些票的 addedAt 更早，是容器回退复活的，不是你加回来的"
                          % (_hist[-1].get("t") or 0, ",".join(str(c) for c in (_hist[-1].get("codes") or []))))
            elif not (isinstance(_hist, list) and _hist):
                print("   · 幽灵防线：暂无拉取观测史（本地副本尚未记录）→ 本轮放行，不因判不出丢票")
        except Exception as _e:
            print("   ⚠️ 幽灵防线自检失败（本轮放行，不影响发布）：%s" % _e)

    # ③ 同步代码文件
    for name in CODE_FILES:
        src = os.path.join(ROOT, name)
        if os.path.exists(src):
            shutil.copy2(src, os.path.join(DEPLOY, name))
    shutil.copy2(os.path.join(ROOT, "public", "index.html"), os.path.join(DEPLOY, "public", "index.html"))
    shutil.copy2(os.path.join(ROOT, "public", "mobile.html"), os.path.join(DEPLOY, "public", "mobile.html"))
    shutil.copy2(os.path.join(ROOT, "public", "manifest.json"), os.path.join(DEPLOY, "public", "manifest.json"))
    shutil.copy2(os.path.join(ROOT, "public", "sw.js"), os.path.join(DEPLOY, "public", "sw.js"))
    # ③a 强制同步 sw.js APP_VER 与 server.js APP_VER，防止 PWA cache-first 钉死旧 mobile.html（ja 轮教训：sw.js 长期硬编码 20261017eo，iz 改了 mobile.html 后手机看不到新功能）
    try:
        _srv_appver = re.search(r"const APP_VER = '(\d{8}[a-z]{2})'", open(os.path.join(ROOT, "server.js"), "r", encoding="utf-8").read())
        if _srv_appver:
            _sw_ver = _srv_appver.group(1)
            for _sw_path in [os.path.join(ROOT, "public", "sw.js"), os.path.join(DEPLOY, "public", "sw.js")]:
                _sw_txt = open(_sw_path, "r", encoding="utf-8").read()
                _sw_new = re.sub(r"const APP_VER = '\d{8}[a-z]{2}'", f"const APP_VER = '{_sw_ver}'", _sw_txt, count=1)
                if _sw_new != _sw_txt:
                    open(_sw_path, "w", encoding="utf-8").write(_sw_new)
                    print("   sw.js APP_VER 已同步为 " + _sw_ver)
    except Exception as _e:
        print("   ⚠️ sw.js APP_VER 同步失败：" + str(_e))
    shutil.copy2(os.path.join(ROOT, "public", "icon.svg"), os.path.join(DEPLOY, "public", "icon.svg"))
    print("③ 代码文件已同步 %d 个" % (len(CODE_FILES) + 5))

    # ③b 全A股K线缓存（.kline_cache）必须随包发布 —— 用户提了四次的「K线数据一定要有」
    #    真凶就在这里：本地补齐到 100%，可发布包里从来没有这个目录，
    #    线上每次重启都从 0 开始补，而东财源已死、只剩腾讯单源，补齐慢到永远追不上。
    #    只同步「最近 10 天内有更新」的文件，避免每轮都搬 75MB（首轮全量，之后增量）。
    _kc_src = os.path.join(ROOT, ".kline_cache")
    _kc_dst = os.path.join(DEPLOY, ".kline_cache")
    _kc_n = 0
    if os.path.isdir(_kc_src):
        os.makedirs(_kc_dst, exist_ok=True)
        _cut = time.time() - 10 * 86400
        for _fn in os.listdir(_kc_src):
            if not _fn.endswith(".json"):
                continue
            _s = os.path.join(_kc_src, _fn)
            _d = os.path.join(_kc_dst, _fn)
            try:
                if os.path.exists(_d) and os.path.getmtime(_d) >= os.path.getmtime(_s):
                    continue
                if os.path.getmtime(_s) < _cut:
                    continue
                shutil.copy2(_s, _d)
                _kc_n += 1
            except Exception:
                pass
        print("   📦 K线缓存已同步 %d 个（包内累计 %d 个）" % (_kc_n, len(os.listdir(_kc_dst))))

    # ⓪d 裁剪发布包内的 K线缓存：只留「最近 3 个月还有数据」的票（死票文件是无界增长源）
    trim_kline_cache(_kc_dst)

    # ④ 本地实例标记为副本：不发企业微信，避免和线上重复推送
    cfg = json.load(open(os.path.join(ROOT, "config.json"), encoding="utf-8"))
    if cfg.get("pushRole") != "replica":
        cfg["pushRole"] = "replica"
        json.dump(cfg, open(os.path.join(ROOT, "config.json"), "w", encoding="utf-8"),
                  ensure_ascii=False, indent=2)
    print("④ 本地实例 pushRole=replica（不外发推送，只更新面板）")

    with open(os.path.join(DEPLOY, "server.js"), encoding="utf-8") as f:
        for line in f:
            if line.startswith("const APP_VER ="):
                print("⑤ 待发布版本:", line.strip())
                break
    warn_untracked(DEPLOY)
    size_gate()
    print("\n✅ 同步完成，可执行发布。")


def warn_untracked(dep_dir):
    """发布自检（2026-10-27 复盘）：扫描发布包，列出未被 git 跟踪的源码文件，
    提示发布者确认非开发残留。纯提示、不拦发布；git 状态判不出时静默跳过（不误报）。"""
    try:
        import subprocess as _sp
        _tracked = set(_sp.check_output(["git", "ls-files"], cwd=ROOT,
                                        stderr=_sp.DEVNULL).decode("utf-8", "ignore").splitlines())
    except Exception:
        return  # 判不出不硬判：git 不可用/出错时静默跳过，避免误报
    _SRC = (".js", ".py", ".html", ".css")
    _hits = []
    for _dp, _dn, _fn in os.walk(dep_dir):
        for _f in _fn:
            if not _f.lower().endswith(_SRC):
                continue
            _rel = os.path.relpath(os.path.join(_dp, _f), dep_dir).replace("\\", "/")
            if _rel not in _tracked:
                _hits.append(_rel)
    if _hits:
        print("\n⚠️ [未跟踪文件提示] 发布包内以下源码未被 git 跟踪，确认非开发残留后再发布：")
        for _h in sorted(_hits):
            print("   · %s" % _h)
        print("   （仅为提示，不阻断发布；若确为有意发布的协作/开发工具请忽略；若部署工具整目录上传 ROOT，另需 git status 核对 ROOT 无未跟踪开发文件）")
    else:
        print("✓ 发布包源码文件全部已被 git 跟踪（无未跟踪残留）")


def backup_local():
    """发布前把本地运行环境存一份，--restore 时用来还原"""
    os.makedirs(BACKUP, exist_ok=True)
    for name in DATA_FILES:
        src = os.path.join(ROOT, name)
        if os.path.exists(src):
            shutil.copy2(src, os.path.join(BACKUP, name))
    print("   本地运行环境已备份到 _local_backup/")


def _restore_machinekey(target_access):
    """把第①步记下的线上 machineKey 写回即将上传的 access.json（根目录那份）。
    返回 True 表示写成功了（令牌跨发版存活），False 表示没有可用密钥（保持原样）。"""
    mkfile = os.path.join(ROOT, ".online_machinekey")
    if not (os.path.exists(mkfile) and os.path.exists(target_access)):
        return False
    mk = open(mkfile, encoding="utf-8").read().strip()
    if not mk:
        return False
    try:
        acc = json.load(open(target_access, encoding="utf-8"))
        if acc.get("machineKey") == mk:
            return True          # 已经一致，无需改动
        acc["machineKey"] = mk
        json.dump(acc, open(target_access, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
        return True
    except Exception as e:
        print("   ⚠️ machineKey 写回失败: %s（本次发布后需重新登录）" % e)
        return False


def apply_to_root():
    """ⓐ 把发布包（= 线上数据 + 本地新代码）铺回根目录，让「发布根目录」这个动作是安全的。
    ⚠️ 血泪教训：发布工具是按【项目根目录】定位线上应用的，直接发根目录会把本地的
       config.json（含 pushRole=replica 副本标记 / syncUpstream 转发配置）和本地
       holdings/paper/stats 一起传上去 —— 结果是线上停止推送 + 线上业务数据被冲掉。
       所以发布前必须先把根目录里的这些文件换成 _deploy_tmp 里的正确版本。"""
    # ⓪c 铺根目录前再数一遍包体：--apply 是把根目录变成「可发布状态」的动作，
    #   若此刻 ROOT 已越过网关上限，后面 deploy 必然 ECONNRESET 白丢一次发布。
    size_gate()
    for name in DATA_FILES + CODE_FILES:
        src = os.path.join(DEPLOY, name)
        if os.path.exists(src):
            shutil.copy2(src, os.path.join(ROOT, name))
    src_html = os.path.join(DEPLOY, "public", "index.html")
    if os.path.exists(src_html):
        shutil.copy2(src_html, os.path.join(ROOT, "public", "index.html"))
    src_mobile = os.path.join(DEPLOY, "public", "mobile.html")
    if os.path.exists(src_mobile):
        shutil.copy2(src_mobile, os.path.join(ROOT, "public", "mobile.html"))
    src_manifest = os.path.join(DEPLOY, "public", "manifest.json")
    if os.path.exists(src_manifest):
        shutil.copy2(src_manifest, os.path.join(ROOT, "public", "manifest.json"))
    src_sw = os.path.join(DEPLOY, "public", "sw.js")
    if os.path.exists(src_sw):
        shutil.copy2(src_sw, os.path.join(ROOT, "public", "sw.js"))
    src_icon = os.path.join(DEPLOY, "public", "icon.svg")
    if os.path.exists(src_icon):
        shutil.copy2(src_icon, os.path.join(ROOT, "public", "icon.svg"))
    # ★ 发布包里 access.json 被 NEVER_SHIP 剔除过，但【根目录】那份仍会随发布上传：
    #   本地 machineKey 与线上不同 → 上传后线上令牌全作废 → 手机每次发版都要重新登录。
    #   这里把第一步记下的线上 machineKey 写回根目录 access.json，令牌即可跨发版存活。
    _mk_restored = _restore_machinekey(os.path.join(ROOT, "access.json"))
    _auth_restored = _restore_access_auth(os.path.join(ROOT, "access.json"))
    print("ⓐ 根目录已铺成发布包内容（config 无 pushRole / 数据为线上版本）")
    if _auth_restored:
        print("   \U0001f510 已沿用线上登录凭据与设备台账 → 你改的密码不会被打回，令牌不必重签")
    print("   → 现在可以发布；发布完成后务必执行: python _publish.py --restore")
    if _mk_restored:
        print("   🔑 已保留线上 machineKey → 现有设备令牌跨本次发版继续有效（无需重新登录）")


def _restore_access_auth(target_access):
    """把第①步记下的【线上凭据 + 设备台账】写回待发布的 access.json。

    与 machineKey 同源同理：access.json 随根目录上传，本地那份是开发副本的旧状态，
    一旦覆盖用户就"改一次版本重新登录一次"，更糟的是他刚改的密码会被打回旧值。
    这里逐字段填回线上值；只有 machineKey 沿用已写好的那个（它与这份数据同源）。"""
    f = os.path.join(BACKUP, ".online_access_auth.json")
    if not (os.path.exists(f) and os.path.exists(target_access)):
        return False
    try:
        auth = json.load(open(f, encoding="utf-8"))
        if not auth or not auth.get("hash"):
            return False
        acc = json.load(open(target_access, encoding="utf-8"))
        keep_mk = acc.get("machineKey")
        for k in ("salt", "hash", "setAt", "gen", "devices", "view"):
            if auth.get(k) is not None:
                acc[k] = auth[k]
        if keep_mk:
            acc["machineKey"] = keep_mk
        json.dump(acc, open(target_access, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
        return True
    except Exception as e:
        print("   ⚠️ 线上凭据回填失败: %s（本次发布后可能需要重新登录）" % e)
        return False


def restore_local():
    """ⓑ 发布结束后把本地运行环境还原（副本标记 + 转发配置 + 本地数据）"""
    if not os.path.isdir(BACKUP):
        raise SystemExit("没有 _local_backup/，无法还原（是不是没跑过 --apply？）")
    for name in DATA_FILES:
        src = os.path.join(BACKUP, name)
        if os.path.exists(src):
            shutil.copy2(src, os.path.join(ROOT, name))
    # 兜底：确保本地一定是副本，绝不能和线上抢着推送
    cfgp = os.path.join(ROOT, "config.json")
    cfg = json.load(open(cfgp, encoding="utf-8"))
    changed = False
    if cfg.get("pushRole") != "replica":
        cfg["pushRole"] = "replica"
        changed = True
    if changed:
        json.dump(cfg, open(cfgp, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    print("ⓑ 本地运行环境已还原（pushRole=replica + 本地数据）")
    refresh_sync_token(cfgp)
    print("   → 记得重启本地服务，让新配置生效")
    print()
    print("ℹ️ 关于发布后的登录态（2026-09-30 起已大幅改善）：")
    print("   ① machineKey：本脚本会在 --apply 时把线上 machineKey 写回待发布的 access.json")
    print("      → 令牌跨发版存活，设备不再被踢。线上还没暴露 machineKey（旧版）时会提示，属一次性代价。")
    print("   ② change(view)：密码没变则返回 unchanged，不动 devices 也不 bump 世代；")
    print("      只有密码【真的改了】才作废旧令牌 —— 别再把这条当例行公事每天重设一遍。")
    print("   ③ 仍建议跑一次 _post_publish.py：它会顺便重签本地转发令牌、同步持仓、重建桌面快捷方式。")
    print("      漏掉这一步 = 刚修好的『换口令后旧令牌仍能登录』漏洞又回来了。")


# 兜底开关：确认「线上就该是空持仓」时才用（例如你刚手动清空了线上）
FORCE_EMPTY_HOLDINGS = "--force-empty-holdings" in sys.argv
if __name__ == "__main__":
    # 🔒 发布闸门（2026-10-27，防并行会话/多 agent 发布打架）：工作区洁净 + 基线对齐 + 发布锁
    import subprocess as _sp, atexit as _atexit, os as _os
    _gp = _sp.run(["node", "_publish_gate.js", "acquire", (sys.argv[1] if len(sys.argv) > 1 else "sync"), "--pid", str(_os.getpid())],
                  capture_output=True, text=True)
    if _gp.returncode != 0:
        print(_gp.stdout)
        print(_gp.stderr)
        raise SystemExit("⛔ 发布闸门拦截（见上），本次发布未执行")
    _atexit.register(lambda: _sp.run(["node", "_publish_gate.js", "release"], capture_output=True))
    arg = sys.argv[1] if len(sys.argv) > 1 else ""
    if arg == "--restore":
        restore_local()
    elif arg == "--apply":
        apply_to_root()
    else:
        main()
        backup_local()
        print("\n下一步: python _publish.py --apply  → 发布 → python _publish.py --restore")
